BEGIN
  SELECT id INTO v_ver FROM public.curriculum_versions WHERE authority = 'DfE' AND code = 'DFE-NC-2014';
  IF v_ver IS NULL THEN RAISE EXCEPTION 'DfE curriculum version missing'; END IF;
  FOR e IN SELECT x FROM jsonb_array_elements($j$[["GB.MAT.1.NPV.1",1,"Number – number and place value","Count to and across 100, forwards and backwards, beginning with 0 or 1, or from any given number"],["GB.MAT.1.NPV.2",1,"Number – number and place value","Count, read and write numbers to 100 in numerals; count in multiples of twos, fives and tens"],["GB.MAT.1.NPV.3",1,"Number – number and place value","Given a number, identify one more and one less"],["GB.MAT.1.NPV.4",1,"Number – number and place value","Identify and represent numbers using objects and pictorial representations including the number line, and use the language of: equal to, more than, less than (fewer), most, least"],["GB.MAT.1.NPV.5",1,"Number – number and place value","Read and write numbers from 1 to 20 in numerals and words."],["GB.MAT.1.NAS.1",1,"Number – addition and subtraction","Read, write and interpret mathematical statements involving addition (+), subtraction (–) and equals (=) signs"],["GB.MAT.1.NAS.2",1,"Number – addition and subtraction","Represent and use number bonds and related subtraction facts within 20"],["GB.MAT.1.NAS.3",1,"Number – addition and subtraction","Add and subtract one-digit and two-digit numbers to 20, including zero"],["GB.MAT.1.NAS.4",1,"Number – addition and subtraction","Solve one-step problems that involve addition and subtraction, using concrete objects and pictorial representations, and missing number problems such as 7 = □ – 9."],["GB.MAT.1.NMD.1",1,"Number – multiplication and division","Solve one-step problems involving multiplication and division, by calculating the answer using concrete objects, pictorial representations and arrays with the support of the teacher."],["GB.MAT.1.NFR.1",1,"Number – fractions","Recognise, find and name a half as one of two equal parts of an object, shape or quantity"],["GB.MAT.1.NFR.2",1,"Number – fractions","Recognise, find and name a quarter as one of four equal parts of an object, shape or quantity."],["GB.MAT.1.MEA.1",1,"Measurement","Compare, describe and solve practical problems for: lengths and heights [for example, long/short, longer/shorter, tall/short, double/half]; mass/weight [for example, heavy/light, heavier than, lighter than]; capacity and volume [for example, full/empty, more than, less than, half, half full, quarter]; time [for example, quicker, slower, earlier, later]"],["GB.MAT.1.MEA.2",1,"Measurement","Measure and begin to record the following: lengths and heights; mass/weight; capacity and volume; time (hours, minutes, seconds)"],["GB.MAT.1.MEA.3",1,"Measurement","Recognise and know the value of different denominations of coins and notes"],["GB.MAT.1.MEA.4",1,"Measurement","Sequence events in chronological order using language [for example, before and after, next, first, today, yesterday, tomorrow, morning, afternoon and evening]"],["GB.MAT.1.MEA.5",1,"Measurement","Recognise and use language relating to dates, including days of the week, weeks, months and years"],["GB.MAT.1.MEA.6",1,"Measurement","Tell the time to the hour and half past the hour and draw the hands on a clock face to show these times."],["GB.MAT.1.GPS.1",1,"Geometry – properties of shapes","Recognise and name common 2-D and 3-D shapes, including: 2-D shapes [for example, rectangles (including squares), circles and triangles]; 3-D shapes [for example, cuboids (including cubes), pyramids and spheres]."],["GB.MAT.1.GPD.1",1,"Geometry – position and direction","Describe position, direction and movement, including whole, half, quarter and three-quarter turns."],["GB.MAT.2.NPV.1",2,"Number – number and place value","Count in steps of 2, 3, and 5 from 0, and in tens from any number, forward and backward"],["GB.MAT.2.NPV.2",2,"Number – number and place value","Recognise the place value of each digit in a two-digit number (tens, ones)"],["GB.MAT.2.NPV.3",2,"Number – number and place value","Identify, represent and estimate numbers using different representations, including the number line"],["GB.MAT.2.NPV.4",2,"Number – number and place value","Compare and order numbers from 0 up to 100; use <, > and = signs"],["GB.MAT.2.NPV.5",2,"Number – number and place value","Read and write numbers to at least 100 in numerals and in words"],["GB.MAT.2.NPV.6",2,"Number – number and place value","Use place value and number facts to solve problems."],["GB.MAT.2.NAS.1",2,"Number – addition and subtraction","Solve problems with addition and subtraction: using concrete objects and pictorial representations, including those involving numbers, quantities and measures; applying their increasing knowledge of mental and written methods"],["GB.MAT.2.NAS.2",2,"Number – addition and subtraction","Recall and use addition and subtraction facts to 20 fluently, and derive and use related facts up to 100"],["GB.MAT.2.NAS.3",2,"Number – addition and subtraction","Add and subtract numbers using concrete objects, pictorial representations, and mentally, including: a two-digit number and ones; a two-digit number and tens; two two-digit numbers; adding three one-digit numbers"],["GB.MAT.2.NAS.4",2,"Number – addition and subtraction","Show that addition of two numbers can be done in any order (commutative) and subtraction of one number from another cannot"],["GB.MAT.2.NAS.5",2,"Number – addition and subtraction","Recognise and use the inverse relationship between addition and subtraction and use this to check calculations and solve missing number problems."],["GB.MAT.2.NMD.1",2,"Number – multiplication and division","Recall and use multiplication and division facts for the 2, 5 and 10 multiplication tables, including recognising odd and even numbers"],["GB.MAT.2.NMD.2",2,"Number – multiplication and division","Calculate mathematical statements for multiplication and division within the multiplication tables and write them using the multiplication (×), division (÷) and equals (=) signs"],["GB.MAT.2.NMD.3",2,"Number – multiplication and division","Show that multiplication of two numbers can be done in any order (commutative) and division of one number by another cannot"],["GB.MAT.2.NMD.4",2,"Number – multiplication and division","Solve problems involving multiplication and division, using materials, arrays, repeated addition, mental methods, and multiplication and division facts, including problems in contexts."],["GB.MAT.2.NFR.1",2,"Number – fractions","Recognise, find, name and write fractions 1/3, 1/4, 2/4 and 3/4 of a length, shape, set of objects or quantity"],["GB.MAT.2.NFR.2",2,"Number – fractions","Write simple fractions, for example 1/2 of 6 = 3, and recognise the equivalence of 2/4 and 1/2."],["GB.MAT.2.MEA.1",2,"Measurement","Choose and use appropriate standard units to estimate and measure length/height in any direction (m/cm); mass (kg/g); temperature (°C); capacity (litres/ml) to the nearest appropriate unit, using rulers, scales, thermometers and measuring vessels"],["GB.MAT.2.MEA.2",2,"Measurement","Compare and order lengths, mass, volume/capacity and record the results using >, < and ="],["GB.MAT.2.MEA.3",2,"Measurement","Recognise and use symbols for pounds (£) and pence (p); combine amounts to make a particular value"],["GB.MAT.2.MEA.4",2,"Measurement","Find different combinations of coins that equal the same amounts of money"],["GB.MAT.2.MEA.5",2,"Measurement","Solve simple problems in a practical context involving addition and subtraction of money of the same unit, including giving change"],["GB.MAT.2.MEA.6",2,"Measurement","Compare and sequence intervals of time"],["GB.MAT.2.MEA.7",2,"Measurement","Tell and write the time to five minutes, including quarter past/to the hour and draw the hands on a clock face to show these times"],["GB.MAT.2.MEA.8",2,"Measurement","Know the number of minutes in an hour and the number of hours in a day."],["GB.MAT.2.GPS.1",2,"Geometry – properties of shapes","Identify and describe the properties of 2-D shapes, including the number of sides and line symmetry in a vertical line"],["GB.MAT.2.GPS.2",2,"Geometry – properties of shapes","Identify and describe the properties of 3-D shapes, including the number of edges, vertices and faces"],["GB.MAT.2.GPS.3",2,"Geometry – properties of shapes","Identify 2-D shapes on the surface of 3-D shapes, [for example, a circle on a cylinder and a triangle on a pyramid]"],["GB.MAT.2.GPS.4",2,"Geometry – properties of shapes","Compare and sort common 2-D and 3-D shapes and everyday objects."],["GB.MAT.2.GPD.1",2,"Geometry – position and direction","Order and arrange combinations of mathematical objects in patterns and sequences"],["GB.MAT.2.GPD.2",2,"Geometry – position and direction","Use mathematical vocabulary to describe position, direction and movement, including movement in a straight line and distinguishing between rotation as a turn and in terms of right angles for quarter, half and three-quarter turns (clockwise and anti-clockwise)."],["GB.MAT.2.STA.1",2,"Statistics","Interpret and construct simple pictograms, tally charts, block diagrams and simple tables"],["GB.MAT.2.STA.2",2,"Statistics","Ask and answer simple questions by counting the number of objects in each category and sorting the categories by quantity"],["GB.MAT.2.STA.3",2,"Statistics","Ask and answer questions about totalling and comparing categorical data."],["GB.MAT.3.NPV.1",3,"Number – number and place value","Count from 0 in multiples of 4, 8, 50 and 100; find 10 or 100 more or less than a given number"],["GB.MAT.3.NPV.2",3,"Number – number and place value","Recognise the place value of each digit in a three-digit number (hundreds, tens, ones)"],["GB.MAT.3.NPV.3",3,"Number – number and place value","Compare and order numbers up to 1000"],["GB.MAT.3.NPV.4",3,"Number – number and place value","Identify, represent and estimate numbers using different representations"],["GB.MAT.3.NPV.5",3,"Number – number and place value","Read and write numbers up to 1000 in numerals and in words"],["GB.MAT.3.NPV.6",3,"Number – number and place value","Solve number problems and practical problems involving these ideas."],["GB.MAT.3.NAS.1",3,"Number – addition and subtraction","Add and subtract numbers mentally, including: a three-digit number and ones; a three-digit number and tens; a three-digit number and hundreds"],["GB.MAT.3.NAS.2",3,"Number – addition and subtraction","Add and subtract numbers with up to three digits, using formal written methods of columnar addition and subtraction"],["GB.MAT.3.NAS.3",3,"Number – addition and subtraction","Estimate the answer to a calculation and use inverse operations to check answers"],["GB.MAT.3.NAS.4",3,"Number – addition and subtraction","Solve problems, including missing number problems, using number facts, place value, and more complex addition and subtraction."],["GB.MAT.3.NMD.1",3,"Number – multiplication and division","Recall and use multiplication and division facts for the 3, 4 and 8 multiplication tables"],["GB.MAT.3.NMD.2",3,"Number – multiplication and division","Write and calculate mathematical statements for multiplication and division using the multiplication tables that they know, including for two-digit numbers times one-digit numbers, using mental and progressing to formal written methods"],["GB.MAT.3.NMD.3",3,"Number – multiplication and division","Solve problems, including missing number problems, involving multiplication and division, including positive integer scaling problems and correspondence problems in which n objects are connected to m objects."],["GB.MAT.3.NFR.1",3,"Number – fractions","Count up and down in tenths; recognise that tenths arise from dividing an object into 10 equal parts and in dividing one-digit numbers or quantities by 10"],["GB.MAT.3.NFR.2",3,"Number – fractions","Recognise, find and write fractions of a discrete set of objects: unit fractions and non-unit fractions with small denominators"],["GB.MAT.3.NFR.3",3,"Number – fractions","Recognise and use fractions as numbers: unit fractions and non-unit fractions with small denominators"],["GB.MAT.3.NFR.4",3,"Number – fractions","Recognise and show, using diagrams, equivalent fractions with small denominators"],["GB.MAT.3.NFR.5",3,"Number – fractions","Add and subtract fractions with the same denominator within one whole [for example, 5/7 + 1/7 = 6/7]"],["GB.MAT.3.NFR.6",3,"Number – fractions","Compare and order unit fractions, and fractions with the same denominators"],["GB.MAT.3.NFR.7",3,"Number – fractions","Solve problems that involve all of the above."],["GB.MAT.3.MEA.1",3,"Measurement","Measure, compare, add and subtract: lengths (m/cm/mm); mass (kg/g); volume/capacity (l/ml)"],["GB.MAT.3.MEA.2",3,"Measurement","Measure the perimeter of simple 2-D shapes"],["GB.MAT.3.MEA.3",3,"Measurement","Add and subtract amounts of money to give change, using both £ and p in practical contexts"],["GB.MAT.3.MEA.4",3,"Measurement","Tell and write the time from an analogue clock, including using Roman numerals from I to XII, and 12-hour and 24-hour clocks"],["GB.MAT.3.MEA.5",3,"Measurement","Estimate and read time with increasing accuracy to the nearest minute; record and compare time in terms of seconds, minutes and hours; use vocabulary such as o’clock, a.m./p.m., morning, afternoon, noon and midnight"],["GB.MAT.3.MEA.6",3,"Measurement","Know the number of seconds in a minute and the number of days in each month, year and leap year"],["GB.MAT.3.MEA.7",3,"Measurement","Compare durations of events [for example to calculate the time taken by particular events or tasks]."],["GB.MAT.3.GPS.1",3,"Geometry – properties of shapes","Draw 2-D shapes and make 3-D shapes using modelling materials; recognise 3-D shapes in different orientations and describe them"],["GB.MAT.3.GPS.2",3,"Geometry – properties of shapes","Recognise angles as a property of shape or a description of a turn"],["GB.MAT.3.GPS.3",3,"Geometry – properties of shapes","Identify right angles, recognise that two right angles make a half-turn, three make three quarters of a turn and four a complete turn; identify whether angles are greater than or less than a right angle"],["GB.MAT.3.GPS.4",3,"Geometry – properties of shapes","Identify horizontal and vertical lines and pairs of perpendicular and parallel lines."],["GB.MAT.3.STA.1",3,"Statistics","Interpret and present data using bar charts, pictograms and tables"],["GB.MAT.3.STA.2",3,"Statistics","Solve one-step and two-step questions [for example, ‘How many more?’ and ‘How many fewer?’] using information presented in scaled bar charts and pictograms and tables."],["GB.MAT.4.NPV.1",4,"Number – number and place value","Count in multiples of 6, 7, 9, 25 and 1000"],["GB.MAT.4.NPV.2",4,"Number – number and place value","Find 1000 more or less than a given number"],["GB.MAT.4.NPV.3",4,"Number – number and place value","Count backwards through zero to include negative numbers"],["GB.MAT.4.NPV.4",4,"Number – number and place value","Recognise the place value of each digit in a four-digit number (thousands, hundreds, tens, and ones)"],["GB.MAT.4.NPV.5",4,"Number – number and place value","Order and compare numbers beyond 1000"],["GB.MAT.4.NPV.6",4,"Number – number and place value","Identify, represent and estimate numbers using different representations"],["GB.MAT.4.NPV.7",4,"Number – number and place value","Round any number to the nearest 10, 100 or 1000"],["GB.MAT.4.NPV.8",4,"Number – number and place value","Solve number and practical problems that involve all of the above and with increasingly large positive numbers"],["GB.MAT.4.NPV.9",4,"Number – number and place value","Read Roman numerals to 100 (I to C) and know that over time, the numeral system changed to include the concept of zero and place value."],["GB.MAT.4.NAS.1",4,"Number – addition and subtraction","Add and subtract numbers with up to 4 digits using the formal written methods of columnar addition and subtraction where appropriate"],["GB.MAT.4.NAS.2",4,"Number – addition and subtraction","Estimate and use inverse operations to check answers to a calculation"],["GB.MAT.4.NAS.3",4,"Number – addition and subtraction","Solve addition and subtraction two-step problems in contexts, deciding which operations and methods to use and why."],["GB.MAT.4.NMD.1",4,"Number – multiplication and division","Recall multiplication and division facts for multiplication tables up to 12 × 12"],["GB.MAT.4.NMD.2",4,"Number – multiplication and division","Use place value, known and derived facts to multiply and divide mentally, including: multiplying by 0 and 1; dividing by 1; multiplying together three numbers"],["GB.MAT.4.NMD.3",4,"Number – multiplication and division","Recognise and use factor pairs and commutativity in mental calculations"],["GB.MAT.4.NMD.4",4,"Number – multiplication and division","Multiply two-digit and three-digit numbers by a one-digit number using formal written layout"],["GB.MAT.4.NMD.5",4,"Number – multiplication and division","Solve problems involving multiplying and adding, including using the distributive law to multiply two digit numbers by one digit, integer scaling problems and harder correspondence problems such as n objects are connected to m objects."],["GB.MAT.4.NFR.1",4,"Number – fractions (including decimals)","Recognise and show, using diagrams, families of common equivalent fractions"],["GB.MAT.4.NFR.2",4,"Number – fractions (including decimals)","Count up and down in hundredths; recognise that hundredths arise when dividing an object by one hundred and dividing tenths by ten."],["GB.MAT.4.NFR.3",4,"Number – fractions (including decimals)","Solve problems involving increasingly harder fractions to calculate quantities, and fractions to divide quantities, including non-unit fractions where the answer is a whole number"],["GB.MAT.4.NFR.4",4,"Number – fractions (including decimals)","Add and subtract fractions with the same denominator"],["GB.MAT.4.NFR.5",4,"Number – fractions (including decimals)","Recognise and write decimal equivalents of any number of tenths or hundredths"],["GB.MAT.4.NFR.6",4,"Number – fractions (including decimals)","Recognise and write decimal equivalents to 1/4, 1/2, 3/4"],["GB.MAT.4.NFR.7",4,"Number – fractions (including decimals)","Find the effect of dividing a one- or two-digit number by 10 and 100, identifying the value of the digits in the answer as ones, tenths and hundredths"],["GB.MAT.4.NFR.8",4,"Number – fractions (including decimals)","Round decimals with one decimal place to the nearest whole number"],["GB.MAT.4.NFR.9",4,"Number – fractions (including decimals)","Compare numbers with the same number of decimal places up to two decimal places"],["GB.MAT.4.NFR.10",4,"Number – fractions (including decimals)","Solve simple measure and money problems involving fractions and decimals to two decimal places."],["GB.MAT.4.MEA.1",4,"Measurement","Convert between different units of measure [for example, kilometre to metre; hour to minute]"],["GB.MAT.4.MEA.2",4,"Measurement","Measure and calculate the perimeter of a rectilinear figure (including squares) in centimetres and metres"],["GB.MAT.4.MEA.3",4,"Measurement","Find the area of rectilinear shapes by counting squares"],["GB.MAT.4.MEA.4",4,"Measurement","Estimate, compare and calculate different measures, including money in pounds and pence"],["GB.MAT.4.MEA.5",4,"Measurement","Read, write and convert time between analogue and digital 12- and 24-hour clocks"],["GB.MAT.4.MEA.6",4,"Measurement","Solve problems involving converting from hours to minutes; minutes to seconds; years to months; weeks to days."],["GB.MAT.4.GPS.1",4,"Geometry – properties of shapes","Compare and classify geometric shapes, including quadrilaterals and triangles, based on their properties and sizes"],["GB.MAT.4.GPS.2",4,"Geometry – properties of shapes","Identify acute and obtuse angles and compare and order angles up to two right angles by size"],["GB.MAT.4.GPS.3",4,"Geometry – properties of shapes","Identify lines of symmetry in 2-D shapes presented in different orientations"],["GB.MAT.4.GPS.4",4,"Geometry – properties of shapes","Complete a simple symmetric figure with respect to a specific line of symmetry."],["GB.MAT.4.GPD.1",4,"Geometry – position and direction","Describe positions on a 2-D grid as coordinates in the first quadrant"],["GB.MAT.4.GPD.2",4,"Geometry – position and direction","Describe movements between positions as translations of a given unit to the left/right and up/down"],["GB.MAT.4.GPD.3",4,"Geometry – position and direction","Plot specified points and draw sides to complete a given polygon."],["GB.MAT.4.STA.1",4,"Statistics","Interpret and present discrete and continuous data using appropriate graphical methods, including bar charts and time graphs."],["GB.MAT.4.STA.2",4,"Statistics","Solve comparison, sum and difference problems using information presented in bar charts, pictograms, tables and other graphs."],["GB.MAT.5.NPV.1",5,"Number – number and place value","Read, write, order and compare numbers to at least 1 000 000 and determine the value of each digit"],["GB.MAT.5.NPV.2",5,"Number – number and place value","Count forwards or backwards in steps of powers of 10 for any given number up to 1 000 000"],["GB.MAT.5.NPV.3",5,"Number – number and place value","Interpret negative numbers in context, count forwards and backwards with positive and negative whole numbers, including through zero"],["GB.MAT.5.NPV.4",5,"Number – number and place value","Round any number up to 1 000 000 to the nearest 10, 100, 1000, 10 000 and 100 000"],["GB.MAT.5.NPV.5",5,"Number – number and place value","Solve number problems and practical problems that involve all of the above"],["GB.MAT.5.NPV.6",5,"Number – number and place value","Read Roman numerals to 1000 (M) and recognise years written in Roman numerals."],["GB.MAT.5.NAS.1",5,"Number – addition and subtraction","Add and subtract whole numbers with more than 4 digits, including using formal written methods (columnar addition and subtraction)"],["GB.MAT.5.NAS.2",5,"Number – addition and subtraction","Add and subtract numbers mentally with increasingly large numbers"],["GB.MAT.5.NAS.3",5,"Number – addition and subtraction","Use rounding to check answers to calculations and determine, in the context of a problem, levels of accuracy"],["GB.MAT.5.NAS.4",5,"Number – addition and subtraction","Solve addition and subtraction multi-step problems in contexts, deciding which operations and methods to use and why."],["GB.MAT.5.NMD.1",5,"Number – multiplication and division","Identify multiples and factors, including finding all factor pairs of a number, and common factors of two numbers"],["GB.MAT.5.NMD.2",5,"Number – multiplication and division","Know and use the vocabulary of prime numbers, prime factors and composite (non-prime) numbers"],["GB.MAT.5.NMD.3",5,"Number – multiplication and division","Establish whether a number up to 100 is prime and recall prime numbers up to 19"],["GB.MAT.5.NMD.4",5,"Number – multiplication and division","Multiply numbers up to 4 digits by a one- or two-digit number using a formal written method, including long multiplication for two-digit numbers"],["GB.MAT.5.NMD.5",5,"Number – multiplication and division","Multiply and divide numbers mentally drawing upon known facts"],["GB.MAT.5.NMD.6",5,"Number – multiplication and division","Divide numbers up to 4 digits by a one-digit number using the formal written method of short division and interpret remainders appropriately for the context"],["GB.MAT.5.NMD.7",5,"Number – multiplication and division","Multiply and divide whole numbers and those involving decimals by 10, 100 and 1000"],["GB.MAT.5.NMD.8",5,"Number – multiplication and division","Recognise and use square numbers and cube numbers, and the notation for squared (²) and cubed (³)"],["GB.MAT.5.NMD.9",5,"Number – multiplication and division","Solve problems involving multiplication and division including using their knowledge of factors and multiples, squares and cubes"],["GB.MAT.5.NMD.10",5,"Number – multiplication and division","Solve problems involving addition, subtraction, multiplication and division and a combination of these, including understanding the meaning of the equals sign"],["GB.MAT.5.NMD.11",5,"Number – multiplication and division","Solve problems involving multiplication and division, including scaling by simple fractions and problems involving simple rates."],["GB.MAT.5.NFR.1",5,"Number – fractions (including decimals and percentages)","Compare and order fractions whose denominators are all multiples of the same number"],["GB.MAT.5.NFR.2",5,"Number – fractions (including decimals and percentages)","Identify, name and write equivalent fractions of a given fraction, represented visually, including tenths and hundredths"],["GB.MAT.5.NFR.3",5,"Number – fractions (including decimals and percentages)","Recognise mixed numbers and improper fractions and convert from one form to the other and write mathematical statements > 1 as a mixed number [for example, 2/5 + 4/5 = 6/5 = 1 1/5]"],["GB.MAT.5.NFR.4",5,"Number – fractions (including decimals and percentages)","Add and subtract fractions with the same denominator and denominators that are multiples of the same number"],["GB.MAT.5.NFR.5",5,"Number – fractions (including decimals and percentages)","Multiply proper fractions and mixed numbers by whole numbers, supported by materials and diagrams"],["GB.MAT.5.NFR.6",5,"Number – fractions (including decimals and percentages)","Read and write decimal numbers as fractions [for example, 0.71 = 71/100]"],["GB.MAT.5.NFR.7",5,"Number – fractions (including decimals and percentages)","Recognise and use thousandths and relate them to tenths, hundredths and decimal equivalents"],["GB.MAT.5.NFR.8",5,"Number – fractions (including decimals and percentages)","Round decimals with two decimal places to the nearest whole number and to one decimal place"],["GB.MAT.5.NFR.9",5,"Number – fractions (including decimals and percentages)","Read, write, order and compare numbers with up to three decimal places"],["GB.MAT.5.NFR.10",5,"Number – fractions (including decimals and percentages)","Solve problems involving number up to three decimal places"],["GB.MAT.5.NFR.11",5,"Number – fractions (including decimals and percentages)","Recognise the per cent symbol (%) and understand that per cent relates to ‘number of parts per hundred’, and write percentages as a fraction with denominator 100, and as a decimal"],["GB.MAT.5.NFR.12",5,"Number – fractions (including decimals and percentages)","Solve problems which require knowing percentage and decimal equivalents of 1/2, 1/4, 1/5, 2/5, 4/5, and those fractions with a denominator of a multiple of 10 or 25."],["GB.MAT.5.MEA.1",5,"Measurement","Convert between different units of metric measure (for example, kilometre and metre; centimetre and metre; centimetre and millimetre; gram and kilogram; litre and millilitre)"],["GB.MAT.5.MEA.2",5,"Measurement","Understand and use approximate equivalences between metric units and common imperial units such as inches, pounds and pints"],["GB.MAT.5.MEA.3",5,"Measurement","Measure and calculate the perimeter of composite rectilinear shapes in centimetres and metres"],["GB.MAT.5.MEA.4",5,"Measurement","Calculate and compare the area of rectangles (including squares), and including using standard units, square centimetres (cm²) and square metres (m²) and estimate the area of irregular shapes"],["GB.MAT.5.MEA.5",5,"Measurement","Estimate volume [for example, using 1 cm³ blocks to build cuboids (including cubes)] and capacity [for example, using water]"],["GB.MAT.5.MEA.6",5,"Measurement","Solve problems involving converting between units of time"],["GB.MAT.5.MEA.7",5,"Measurement","Use all four operations to solve problems involving measure [for example, length, mass, volume, money] using decimal notation, including scaling."],["GB.MAT.5.GPS.1",5,"Geometry – properties of shapes","Identify 3-D shapes, including cubes and other cuboids, from 2-D representations"],["GB.MAT.5.GPS.2",5,"Geometry – properties of shapes","Know angles are measured in degrees: estimate and compare acute, obtuse and reflex angles"],["GB.MAT.5.GPS.3",5,"Geometry – properties of shapes","Draw given angles, and measure them in degrees (°)"],["GB.MAT.5.GPS.4",5,"Geometry – properties of shapes","Identify: angles at a point and one whole turn (total 360°); angles at a point on a straight line and 1/2 a turn (total 180°); other multiples of 90°"],["GB.MAT.5.GPS.5",5,"Geometry – properties of shapes","Use the properties of rectangles to deduce related facts and find missing lengths and angles"],["GB.MAT.5.GPS.6",5,"Geometry – properties of shapes","Distinguish between regular and irregular polygons based on reasoning about equal sides and angles."],["GB.MAT.5.GPD.1",5,"Geometry – position and direction","Identify, describe and represent the position of a shape following a reflection or translation, using the appropriate language, and know that the shape has not changed."],["GB.MAT.5.STA.1",5,"Statistics","Solve comparison, sum and difference problems using information presented in a line graph"],["GB.MAT.5.STA.2",5,"Statistics","Complete, read and interpret information in tables, including timetables."],["GB.MAT.6.NPV.1",6,"Number – number and place value","Read, write, order and compare numbers up to 10 000 000 and determine the value of each digit"],["GB.MAT.6.NPV.2",6,"Number – number and place value","Round any whole number to a required degree of accuracy"],["GB.MAT.6.NPV.3",6,"Number – number and place value","Use negative numbers in context, and calculate intervals across zero"],["GB.MAT.6.NPV.4",6,"Number – number and place value","Solve number and practical problems that involve all of the above."],["GB.MAT.6.NOP.1",6,"Number – addition, subtraction, multiplication and division","Multiply multi-digit numbers up to 4 digits by a two-digit whole number using the formal written method of long multiplication"],["GB.MAT.6.NOP.2",6,"Number – addition, subtraction, multiplication and division","Divide numbers up to 4 digits by a two-digit whole number using the formal written method of long division, and interpret remainders as whole number remainders, fractions, or by rounding, as appropriate for the context"],["GB.MAT.6.NOP.3",6,"Number – addition, subtraction, multiplication and division","Divide numbers up to 4 digits by a two-digit number using the formal written method of short division where appropriate, interpreting remainders according to the context"],["GB.MAT.6.NOP.4",6,"Number – addition, subtraction, multiplication and division","Perform mental calculations, including with mixed operations and large numbers"],["GB.MAT.6.NOP.5",6,"Number – addition, subtraction, multiplication and division","Identify common factors, common multiples and prime numbers"],["GB.MAT.6.NOP.6",6,"Number – addition, subtraction, multiplication and division","Use their knowledge of the order of operations to carry out calculations involving the four operations"],["GB.MAT.6.NOP.7",6,"Number – addition, subtraction, multiplication and division","Solve addition and subtraction multi-step problems in contexts, deciding which operations and methods to use and why"],["GB.MAT.6.NOP.8",6,"Number – addition, subtraction, multiplication and division","Solve problems involving addition, subtraction, multiplication and division"],["GB.MAT.6.NOP.9",6,"Number – addition, subtraction, multiplication and division","Use estimation to check answers to calculations and determine, in the context of a problem, an appropriate degree of accuracy."],["GB.MAT.6.NFR.1",6,"Number – fractions (including decimals and percentages)","Use common factors to simplify fractions; use common multiples to express fractions in the same denomination"],["GB.MAT.6.NFR.2",6,"Number – fractions (including decimals and percentages)","Compare and order fractions, including fractions > 1"],["GB.MAT.6.NFR.3",6,"Number – fractions (including decimals and percentages)","Add and subtract fractions with different denominators and mixed numbers, using the concept of equivalent fractions"],["GB.MAT.6.NFR.4",6,"Number – fractions (including decimals and percentages)","Multiply simple pairs of proper fractions, writing the answer in its simplest form [for example, 1/4 × 1/2 = 1/8]"],["GB.MAT.6.NFR.5",6,"Number – fractions (including decimals and percentages)","Divide proper fractions by whole numbers [for example, 1/3 ÷ 2 = 1/6]"],["GB.MAT.6.NFR.6",6,"Number – fractions (including decimals and percentages)","Associate a fraction with division and calculate decimal fraction equivalents [for example, 0.375] for a simple fraction [for example, 3/8]"],["GB.MAT.6.NFR.7",6,"Number – fractions (including decimals and percentages)","Identify the value of each digit in numbers given to three decimal places and multiply and divide numbers by 10, 100 and 1000 giving answers up to three decimal places"],["GB.MAT.6.NFR.8",6,"Number – fractions (including decimals and percentages)","Multiply one-digit numbers with up to two decimal places by whole numbers"],["GB.MAT.6.NFR.9",6,"Number – fractions (including decimals and percentages)","Use written division methods in cases where the answer has up to two decimal places"],["GB.MAT.6.NFR.10",6,"Number – fractions (including decimals and percentages)","Solve problems which require answers to be rounded to specified degrees of accuracy"],["GB.MAT.6.NFR.11",6,"Number – fractions (including decimals and percentages)","Recall and use equivalences between simple fractions, decimals and percentages, including in different contexts."],["GB.MAT.6.RAP.1",6,"Ratio and proportion","Solve problems involving the relative sizes of two quantities where missing values can be found by using integer multiplication and division facts"],["GB.MAT.6.RAP.2",6,"Ratio and proportion","Solve problems involving the calculation of percentages [for example, of measures, and such as 15% of 360] and the use of percentages for comparison"],["GB.MAT.6.RAP.3",6,"Ratio and proportion","Solve problems involving similar shapes where the scale factor is known or can be found"],["GB.MAT.6.RAP.4",6,"Ratio and proportion","Solve problems involving unequal sharing and grouping using knowledge of fractions and multiples."],["GB.MAT.6.ALG.1",6,"Algebra","Use simple formulae"],["GB.MAT.6.ALG.2",6,"Algebra","Generate and describe linear number sequences"],["GB.MAT.6.ALG.3",6,"Algebra","Express missing number problems algebraically"],["GB.MAT.6.ALG.4",6,"Algebra","Find pairs of numbers that satisfy an equation with two unknowns"],["GB.MAT.6.ALG.5",6,"Algebra","Enumerate possibilities of combinations of two variables."],["GB.MAT.6.MEA.1",6,"Measurement","Solve problems involving the calculation and conversion of units of measure, using decimal notation up to three decimal places where appropriate"],["GB.MAT.6.MEA.2",6,"Measurement","Use, read, write and convert between standard units, converting measurements of length, mass, volume and time from a smaller unit of measure to a larger unit, and vice versa, using decimal notation to up to three decimal places"],["GB.MAT.6.MEA.3",6,"Measurement","Convert between miles and kilometres"],["GB.MAT.6.MEA.4",6,"Measurement","Recognise that shapes with the same areas can have different perimeters and vice versa"],["GB.MAT.6.MEA.5",6,"Measurement","Recognise when it is possible to use formulae for area and volume of shapes"],["GB.MAT.6.MEA.6",6,"Measurement","Calculate the area of parallelograms and triangles"],["GB.MAT.6.MEA.7",6,"Measurement","Calculate, estimate and compare volume of cubes and cuboids using standard units, including cubic centimetres (cm³) and cubic metres (m³), and extending to other units [for example, mm³ and km³]."],["GB.MAT.6.GPS.1",6,"Geometry – properties of shapes","Draw 2-D shapes using given dimensions and angles"],["GB.MAT.6.GPS.2",6,"Geometry – properties of shapes","Recognise, describe and build simple 3-D shapes, including making nets"],["GB.MAT.6.GPS.3",6,"Geometry – properties of shapes","Compare and classify geometric shapes based on their properties and sizes and find unknown angles in any triangles, quadrilaterals, and regular polygons"],["GB.MAT.6.GPS.4",6,"Geometry – properties of shapes","Illustrate and name parts of circles, including radius, diameter and circumference and know that the diameter is twice the radius"],["GB.MAT.6.GPS.5",6,"Geometry – properties of shapes","Recognise angles where they meet at a point, are on a straight line, or are vertically opposite, and find missing angles."],["GB.MAT.6.GPD.1",6,"Geometry – position and direction","Describe positions on the full coordinate grid (all four quadrants)"],["GB.MAT.6.GPD.2",6,"Geometry – position and direction","Draw and translate simple shapes on the coordinate plane, and reflect them in the axes."],["GB.MAT.6.STA.1",6,"Statistics","Interpret and construct pie charts and line graphs and use these to solve problems"],["GB.MAT.6.STA.2",6,"Statistics","Calculate and interpret the mean as an average."]]$j$::jsonb) AS t(x) LOOP
    v_grade := (e->>1) || '. sınıf';
    v_level := CASE WHEN (e->>1)::int <= 4 THEN 'ilkokul' WHEN (e->>1)::int <= 8 THEN 'ortaokul' ELSE 'lise' END;
    v_ks := CASE WHEN (e->>1)::int <= 2 THEN 'KS1' WHEN (e->>1)::int <= 6 THEN 'KS2' WHEN (e->>1)::int <= 9 THEN 'KS3' ELSE 'KS4' END;
    v_unit_label := e->>2;
    v_topic_label := split_part(e->>2, ' – ', 1);
    SELECT id INTO v_subject FROM public.learning_graph_nodes
      WHERE node_type = 'subject' AND subject = 'Matematik' AND grade = v_grade AND is_active ORDER BY created_at LIMIT 1;
    IF v_subject IS NULL THEN RAISE EXCEPTION 'Matematik subject node missing for %', v_grade; END IF;

    INSERT INTO public.learning_graph_nodes (node_key, node_type, label, subject, grade, level, source_type, metadata, is_active)
    VALUES ('unit:gb:' || md5(v_grade || '|' || v_unit_label), 'unit', v_unit_label, 'Matematik', v_grade, v_level, 'curriculum',
      jsonb_build_object('catalog_version', 'v1', 'verification_status', 'verified', 'country', 'GB', 'curriculum_version_id', v_ver), true)
    ON CONFLICT (node_key) DO UPDATE SET updated_at = now() RETURNING id INTO v_unit;
    INSERT INTO public.learning_graph_edges (source_node_id, target_node_id, edge_type, confidence, rationale, source_type, is_verified, curriculum_version_id)
    VALUES (v_unit, v_subject, 'part_of', 1.000, 'DfE Ulusal Müfredatı: ünite - ders bağlantısı', 'curriculum', true, v_ver)
    ON CONFLICT (source_node_id, target_node_id, edge_type) DO NOTHING;

    INSERT INTO public.learning_graph_nodes (node_key, node_type, label, subject, grade, level, source_type, metadata, is_active)
    VALUES ('topic:gb:' || md5(v_grade || '|' || v_unit_label || '|' || v_topic_label), 'topic', v_topic_label, 'Matematik', v_grade, v_level, 'curriculum',
      jsonb_build_object('catalog_version', 'v1', 'verification_status', 'verified', 'country', 'GB', 'curriculum_version_id', v_ver), true)
    ON CONFLICT (node_key) DO UPDATE SET updated_at = now() RETURNING id INTO v_topic;
    INSERT INTO public.learning_graph_edges (source_node_id, target_node_id, edge_type, confidence, rationale, source_type, is_verified, curriculum_version_id)
    VALUES (v_topic, v_unit, 'part_of', 1.000, 'DfE Ulusal Müfredatı: konu - ünite bağlantısı', 'curriculum', true, v_ver)
    ON CONFLICT (source_node_id, target_node_id, edge_type) DO NOTHING;

    INSERT INTO public.learning_graph_nodes (node_key, node_type, label, subject, grade, level, source_type, metadata, is_active)
    VALUES ('objective:catalog:' || md5(lower(e->>0)), 'learning_objective', e->>3, 'Matematik', v_grade, v_level, 'objective_import',
      jsonb_build_object('objective_code', e->>0, 'imported_from', 'gov.uk'), true)
    ON CONFLICT (node_key) DO UPDATE SET updated_at = now() RETURNING id INTO v_obj;
    INSERT INTO public.learning_graph_edges (source_node_id, target_node_id, edge_type, confidence, rationale, source_type, is_verified, curriculum_version_id)
    VALUES (v_obj, v_topic, 'part_of', 1.000, 'DfE Ulusal Müfredatı: kazanım - konu bağlantısı', 'objective_import', true, v_ver)
    ON CONFLICT (source_node_id, target_node_id, edge_type) DO NOTHING;

    INSERT INTO public.learning_objective_catalog
      (objective_code, title, level, grade, subject, unit, topic, source_type, source_reference, verification_status, metadata,
       graph_node_id, topic_node_id, curriculum_version_id)
    VALUES (e->>0, e->>3, v_level, v_grade, 'Matematik', v_unit_label, v_topic_label, 'import',
      'DfE, National curriculum in England: mathematics programmes of study, ' || v_ks || ' (Year ' || (e->>1) || '), ' || v_unit_label || ' (gov.uk, Open Government Licence v3.0)',
      'verified',
      jsonb_build_object('imported_from', 'gov.uk', 'country', 'GB', 'uk_year', (e->>1)::int, 'key_stage', v_ks,
        'higher_tier_content', coalesce((e->>4)::boolean, false),
        'note', 'Year N maps to grade N; KS3/KS4 statements are listed for each year of the key stage'),
      v_obj, v_topic, v_ver)
    ON CONFLICT (objective_code) DO NOTHING;
  END LOOP;
END
$gb$;

DO $gb$
DECLARE
  e jsonb; e0 jsonb; y int; v_ver uuid; v_subject uuid; v_unit uuid; v_topic uuid; v_obj uuid;
  v_grade text; v_level text; v_ks text; v_unit_label text; v_topic_label text;
BEGIN
  SELECT id INTO v_ver FROM public.curriculum_versions WHERE authority = 'DfE' AND code = 'DFE-NC-2014';
  IF v_ver IS NULL THEN RAISE EXCEPTION 'DfE curriculum version missing'; END IF;
  FOR e0 IN SELECT x FROM jsonb_array_elements($j$[["GB.MAT.{Y}.NUM.1","7,8,9","Number","Understand and use place value for decimals, measures and integers of any size"],["GB.MAT.{Y}.NUM.2","7,8,9","Number","Order positive and negative integers, decimals and fractions; use the number line as a model for ordering of the real numbers; use the symbols =, ≠, <, >, ≤, ≥"],["GB.MAT.{Y}.NUM.3","7,8,9","Number","Use the concepts and vocabulary of prime numbers, factors (or divisors), multiples, common factors, common multiples, highest common factor, lowest common multiple, prime factorisation, including using product notation and the unique factorisation property"],["GB.MAT.{Y}.NUM.4","7,8,9","Number","Use the four operations, including formal written methods, applied to integers, decimals, proper and improper fractions, and mixed numbers, all both positive and negative"],["GB.MAT.{Y}.NUM.5","7,8,9","Number","Use conventional notation for the priority of operations, including brackets, powers, roots and reciprocals"],["GB.MAT.{Y}.NUM.6","7,8,9","Number","Recognise and use relationships between operations including inverse operations"],["GB.MAT.{Y}.NUM.7","7,8,9","Number","Use integer powers and associated real roots (square, cube and higher), recognise powers of 2, 3, 4, 5 and distinguish between exact representations of roots and their decimal approximations"],["GB.MAT.{Y}.NUM.8","7,8,9","Number","Interpret and compare numbers in standard form A × 10ⁿ, 1 ≤ A < 10, where n is a positive or negative integer or zero"],["GB.MAT.{Y}.NUM.9","7,8,9","Number","Work interchangeably with terminating decimals and their corresponding fractions (such as 3.5 and 7/2 or 0.375 and 3/8)"],["GB.MAT.{Y}.NUM.10","7,8,9","Number","Define percentage as ‘number of parts per hundred’, interpret percentages and percentage changes as a fraction or a decimal, interpret these multiplicatively, express one quantity as a percentage of another, compare two quantities using percentages, and work with percentages greater than 100%"],["GB.MAT.{Y}.NUM.11","7,8,9","Number","Interpret fractions and percentages as operators"],["GB.MAT.{Y}.NUM.12","7,8,9","Number","Use standard units of mass, length, time, money and other measures, including with decimal quantities"],["GB.MAT.{Y}.NUM.13","7,8,9","Number","Round numbers and measures to an appropriate degree of accuracy [for example, to a number of decimal places or significant figures]"],["GB.MAT.{Y}.NUM.14","7,8,9","Number","Use approximation through rounding to estimate answers and calculate possible resulting errors expressed using inequality notation a<x≤b"],["GB.MAT.{Y}.NUM.15","7,8,9","Number","Use a calculator and other technologies to calculate results accurately and then interpret them appropriately"],["GB.MAT.{Y}.NUM.16","7,8,9","Number","Appreciate the infinite nature of the sets of integers, real and rational numbers."],["GB.MAT.{Y}.ALG.1","7,8,9","Algebra","Use and interpret algebraic notation, including: ab in place of a × b; 3y in place of y + y + y and 3 × y; a² in place of a × a, a³ in place of a × a × a; a²b in place of a × a × b; a/b in place of a ÷ b; coefficients written as fractions rather than as decimals; brackets"],["GB.MAT.{Y}.ALG.2","7,8,9","Algebra","Substitute numerical values into formulae and expressions, including scientific formulae"],["GB.MAT.{Y}.ALG.3","7,8,9","Algebra","Understand and use the concepts and vocabulary of expressions, equations, inequalities, terms and factors"],["GB.MAT.{Y}.ALG.4","7,8,9","Algebra","Simplify and manipulate algebraic expressions to maintain equivalence by: collecting like terms; multiplying a single term over a bracket; taking out common factors; expanding products of two or more binomials"],["GB.MAT.{Y}.ALG.5","7,8,9","Algebra","Understand and use standard mathematical formulae; rearrange formulae to change the subject"],["GB.MAT.{Y}.ALG.6","7,8,9","Algebra","Model situations or procedures by translating them into algebraic expressions or formulae and by using graphs"],["GB.MAT.{Y}.ALG.7","7,8,9","Algebra","Use algebraic methods to solve linear equations in one variable (including all forms that require rearrangement)"],["GB.MAT.{Y}.ALG.8","7,8,9","Algebra","Work with coordinates in all four quadrants"],["GB.MAT.{Y}.ALG.9","7,8,9","Algebra","Recognise, sketch and produce graphs of linear and quadratic functions of one variable with appropriate scaling, using equations in x and y and the Cartesian plane"],["GB.MAT.{Y}.ALG.10","7,8,9","Algebra","Interpret mathematical relationships both algebraically and graphically"],["GB.MAT.{Y}.ALG.11","7,8,9","Algebra","Reduce a given linear equation in two variables to the standard form y = mx + c; calculate and interpret gradients and intercepts of graphs of such linear equations numerically, graphically and algebraically"],["GB.MAT.{Y}.ALG.12","7,8,9","Algebra","Use linear and quadratic graphs to estimate values of y for given values of x and vice versa and to find approximate solutions of simultaneous linear equations"],["GB.MAT.{Y}.ALG.13","7,8,9","Algebra","Find approximate solutions to contextual problems from given graphs of a variety of functions, including piece-wise linear, exponential and reciprocal graphs"],["GB.MAT.{Y}.ALG.14","7,8,9","Algebra","Generate terms of a sequence from either a term-to-term or a position-to-term rule"],["GB.MAT.{Y}.ALG.15","7,8,9","Algebra","Recognise arithmetic sequences and find the nth term"],["GB.MAT.{Y}.ALG.16","7,8,9","Algebra","Recognise geometric sequences and appreciate other sequences that arise."],["GB.MAT.{Y}.RPR.1","7,8,9","Ratio, proportion and rates of change","Change freely between related standard units [for example time, length, area, volume/capacity, mass]"],["GB.MAT.{Y}.RPR.2","7,8,9","Ratio, proportion and rates of change","Use scale factors, scale diagrams and maps"],["GB.MAT.{Y}.RPR.3","7,8,9","Ratio, proportion and rates of change","Express one quantity as a fraction of another, where the fraction is less than 1 and greater than 1"],["GB.MAT.{Y}.RPR.4","7,8,9","Ratio, proportion and rates of change","Use ratio notation, including reduction to simplest form"],["GB.MAT.{Y}.RPR.5","7,8,9","Ratio, proportion and rates of change","Divide a given quantity into two parts in a given part:part or part:whole ratio; express the division of a quantity into two parts as a ratio"],["GB.MAT.{Y}.RPR.6","7,8,9","Ratio, proportion and rates of change","Understand that a multiplicative relationship between two quantities can be expressed as a ratio or a fraction"],["GB.MAT.{Y}.RPR.7","7,8,9","Ratio, proportion and rates of change","Relate the language of ratios and the associated calculations to the arithmetic of fractions and to linear functions"],["GB.MAT.{Y}.RPR.8","7,8,9","Ratio, proportion and rates of change","Solve problems involving percentage change, including: percentage increase, decrease and original value problems and simple interest in financial mathematics"],["GB.MAT.{Y}.RPR.9","7,8,9","Ratio, proportion and rates of change","Solve problems involving direct and inverse proportion, including graphical and algebraic representations"],["GB.MAT.{Y}.RPR.10","7,8,9","Ratio, proportion and rates of change","Use compound units such as speed, unit pricing and density to solve problems."],["GB.MAT.{Y}.GEO.1","7,8,9","Geometry and measures","Derive and apply formulae to calculate and solve problems involving: perimeter and area of triangles, parallelograms, trapezia, volume of cuboids (including cubes) and other prisms (including cylinders)"],["GB.MAT.{Y}.GEO.2","7,8,9","Geometry and measures","Calculate and solve problems involving: perimeters of 2-D shapes (including circles), areas of circles and composite shapes"],["GB.MAT.{Y}.GEO.3","7,8,9","Geometry and measures","Draw and measure line segments and angles in geometric figures, including interpreting scale drawings"],["GB.MAT.{Y}.GEO.4","7,8,9","Geometry and measures","Derive and use the standard ruler and compass constructions (perpendicular bisector of a line segment, constructing a perpendicular to a given line from/at a given point, bisecting a given angle); recognise and use the perpendicular distance from a point to a line as the shortest distance to the line"],["GB.MAT.{Y}.GEO.5","7,8,9","Geometry and measures","Describe, sketch and draw using conventional terms and notations: points, lines, parallel lines, perpendicular lines, right angles, regular polygons, and other polygons that are reflectively and rotationally symmetric"],["GB.MAT.{Y}.GEO.6","7,8,9","Geometry and measures","Use the standard conventions for labelling the sides and angles of triangle ABC, and know and use the criteria for congruence of triangles"],["GB.MAT.{Y}.GEO.7","7,8,9","Geometry and measures","Derive and illustrate properties of triangles, quadrilaterals, circles, and other plane figures [for example, equal lengths and angles] using appropriate language and technologies"],["GB.MAT.{Y}.GEO.8","7,8,9","Geometry and measures","Identify properties of, and describe the results of, translations, rotations and reflections applied to given figures"],["GB.MAT.{Y}.GEO.9","7,8,9","Geometry and measures","Identify and construct congruent triangles, and construct similar shapes by enlargement, with and without coordinate grids"],["GB.MAT.{Y}.GEO.10","7,8,9","Geometry and measures","Apply the properties of angles at a point, angles at a point on a straight line, vertically opposite angles"],["GB.MAT.{Y}.GEO.11","7,8,9","Geometry and measures","Understand and use the relationship between parallel lines and alternate and corresponding angles"],["GB.MAT.{Y}.GEO.12","7,8,9","Geometry and measures","Derive and use the sum of angles in a triangle and use it to deduce the angle sum in any polygon, and to derive properties of regular polygons"],["GB.MAT.{Y}.GEO.13","7,8,9","Geometry and measures","Apply angle facts, triangle congruence, similarity and properties of quadrilaterals to derive results about angles and sides, including Pythagoras’ Theorem, and use known results to obtain simple proofs"],["GB.MAT.{Y}.GEO.14","7,8,9","Geometry and measures","Use Pythagoras’ Theorem and trigonometric ratios in similar triangles to solve problems involving right-angled triangles"],["GB.MAT.{Y}.GEO.15","7,8,9","Geometry and measures","Use the properties of faces, surfaces, edges and vertices of cubes, cuboids, prisms, cylinders, pyramids, cones and spheres to solve problems in 3-D"],["GB.MAT.{Y}.GEO.16","7,8,9","Geometry and measures","Interpret mathematical relationships both algebraically and geometrically."],["GB.MAT.{Y}.PRO.1","7,8,9","Probability","Record, describe and analyse the frequency of outcomes of simple probability experiments involving randomness, fairness, equally and unequally likely outcomes, using appropriate language and the 0-1 probability scale"],["GB.MAT.{Y}.PRO.2","7,8,9","Probability","Understand that the probabilities of all possible outcomes sum to 1"],["GB.MAT.{Y}.PRO.3","7,8,9","Probability","Enumerate sets and unions/intersections of sets systematically, using tables, grids and Venn diagrams"],["GB.MAT.{Y}.PRO.4","7,8,9","Probability","Generate theoretical sample spaces for single and combined events with equally likely, mutually exclusive outcomes and use these to calculate theoretical probabilities."],["GB.MAT.{Y}.STA.1","7,8,9","Statistics","Describe, interpret and compare observed distributions of a single variable through: appropriate graphical representation involving discrete, continuous and grouped data; and appropriate measures of central tendency (mean, mode, median) and spread (range, consideration of outliers)"],["GB.MAT.{Y}.STA.2","7,8,9","Statistics","Construct and interpret appropriate tables, charts, and diagrams, including frequency tables, bar charts, pie charts, and pictograms for categorical data, and vertical line (or bar) charts for ungrouped and grouped numerical data"],["GB.MAT.{Y}.STA.3","7,8,9","Statistics","Describe simple mathematical relationships between two variables (bivariate data) in observational and experimental contexts and illustrate using scatter graphs."]]$j$::jsonb) AS t(x) LOOP
  FOREACH y IN ARRAY string_to_array(e0->>1, ',')::int[] LOOP
    e := jsonb_build_array(replace(e0->>0, '{Y}', y::text), y, e0->>2, e0->>3, e0->4);
    v_grade := (e->>1) || '. sınıf';
    v_level := CASE WHEN (e->>1)::int <= 4 THEN 'ilkokul' WHEN (e->>1)::int <= 8 THEN 'ortaokul' ELSE 'lise' END;
    v_ks := CASE WHEN (e->>1)::int <= 2 THEN 'KS1' WHEN (e->>1)::int <= 6 THEN 'KS2' WHEN (e->>1)::int <= 9 THEN 'KS3' ELSE 'KS4' END;
    v_unit_label := e->>2;
    v_topic_label := split_part(e->>2, ' – ', 1);
    SELECT id INTO v_subject FROM public.learning_graph_nodes
      WHERE node_type = 'subject' AND subject = 'Matematik' AND grade = v_grade AND is_active ORDER BY created_at LIMIT 1;
    IF v_subject IS NULL THEN RAISE EXCEPTION 'Matematik subject node missing for %', v_grade; END IF;

    INSERT INTO public.learning_graph_nodes (node_key, node_type, label, subject, grade, level, source_type, metadata, is_active)
    VALUES ('unit:gb:' || md5(v_grade || '|' || v_unit_label), 'unit', v_unit_label, 'Matematik', v_grade, v_level, 'curriculum',
      jsonb_build_object('catalog_version', 'v1', 'verification_status', 'verified', 'country', 'GB', 'curriculum_version_id', v_ver), true)
    ON CONFLICT (node_key) DO UPDATE SET updated_at = now() RETURNING id INTO v_unit;
    INSERT INTO public.learning_graph_edges (source_node_id, target_node_id, edge_type, confidence, rationale, source_type, is_verified, curriculum_version_id)
    VALUES (v_unit, v_subject, 'part_of', 1.000, 'DfE Ulusal Müfredatı: ünite - ders bağlantısı', 'curriculum', true, v_ver)
    ON CONFLICT (source_node_id, target_node_id, edge_type) DO NOTHING;

    INSERT INTO public.learning_graph_nodes (node_key, node_type, label, subject, grade, level, source_type, metadata, is_active)
    VALUES ('topic:gb:' || md5(v_grade || '|' || v_unit_label || '|' || v_topic_label), 'topic', v_topic_label, 'Matematik', v_grade, v_level, 'curriculum',
      jsonb_build_object('catalog_version', 'v1', 'verification_status', 'verified', 'country', 'GB', 'curriculum_version_id', v_ver), true)
    ON CONFLICT (node_key) DO UPDATE SET updated_at = now() RETURNING id INTO v_topic;
    INSERT INTO public.learning_graph_edges (source_node_id, target_node_id, edge_type, confidence, rationale, source_type, is_verified, curriculum_version_id)
    VALUES (v_topic, v_unit, 'part_of', 1.000, 'DfE Ulusal Müfredatı: konu - ünite bağlantısı', 'curriculum', true, v_ver)
    ON CONFLICT (source_node_id, target_node_id, edge_type) DO NOTHING;

    INSERT INTO public.learning_graph_nodes (node_key, node_type, label, subject, grade, level, source_type, metadata, is_active)
    VALUES ('objective:catalog:' || md5(lower(e->>0)), 'learning_objective', e->>3, 'Matematik', v_grade, v_level, 'objective_import',
      jsonb_build_object('objective_code', e->>0, 'imported_from', 'gov.uk'), true)
    ON CONFLICT (node_key) DO UPDATE SET updated_at = now() RETURNING id INTO v_obj;
    INSERT INTO public.learning_graph_edges (source_node_id, target_node_id, edge_type, confidence, rationale, source_type, is_verified, curriculum_version_id)
    VALUES (v_obj, v_topic, 'part_of', 1.000, 'DfE Ulusal Müfredatı: kazanım - konu bağlantısı', 'objective_import', true, v_ver)
    ON CONFLICT (source_node_id, target_node_id, edge_type) DO NOTHING;

    INSERT INTO public.learning_objective_catalog
      (objective_code, title, level, grade, subject, unit, topic, source_type, source_reference, verification_status, metadata,
