        'note', 'Year N maps to grade N; KS3/KS4 statements are listed for each year of the key stage'),
      v_obj, v_topic, v_ver)
    ON CONFLICT (objective_code) DO NOTHING;
  END LOOP;
  END LOOP;
END
$gb$;

DO $gb$
DECLARE
  e jsonb; e0 jsonb; y int; v_ver uuid; v_subject uuid; v_unit uuid; v_topic uuid; v_obj uuid;
  v_grade text; v_level text; v_ks text; v_unit_label text; v_topic_label text;
BEGIN
  SELECT id INTO v_ver FROM public.curriculum_versions WHERE authority = 'DfE' AND code = 'DFE-NC-2014';
  IF v_ver IS NULL THEN RAISE EXCEPTION 'DfE curriculum version missing'; END IF;
  FOR e0 IN SELECT x FROM jsonb_array_elements($j$[["GB.MAT.{Y}.NUM.1","10,11","Number","Apply systematic listing strategies, including use of the product rule for counting",true],["GB.MAT.{Y}.NUM.2","10,11","Number","Estimate powers and roots of any given positive number",true],["GB.MAT.{Y}.NUM.3","10,11","Number","Calculate with roots, and with integer and fractional indices",true],["GB.MAT.{Y}.NUM.4","10,11","Number","Calculate exactly with fractions, surds and multiples of π; simplify surd expressions involving squares [for example √12 = √(4×3) = √4 × √3 = 2√3] and rationalise denominators",true],["GB.MAT.{Y}.NUM.5","10,11","Number","Calculate with numbers in standard form A × 10ⁿ, where 1 ≤ A < 10 and n is an integer"],["GB.MAT.{Y}.NUM.6","10,11","Number","Change recurring decimals into their corresponding fractions and vice versa",true],["GB.MAT.{Y}.NUM.7","10,11","Number","Identify and work with fractions in ratio problems"],["GB.MAT.{Y}.NUM.8","10,11","Number","Apply and interpret limits of accuracy when rounding or truncating, including upper and lower bounds.",true],["GB.MAT.{Y}.ALG.1","10,11","Algebra","Know the difference between an equation and an identity; argue mathematically to show algebraic expressions are equivalent, and use algebra to support and construct arguments and proofs",true],["GB.MAT.{Y}.ALG.2","10,11","Algebra","Where appropriate, interpret simple expressions as functions with inputs and outputs; interpret the reverse process as the ‘inverse function’; interpret the succession of two functions as a ‘composite function’",true],["GB.MAT.{Y}.ALG.3","10,11","Algebra","Use the form y = mx + c to identify parallel and perpendicular lines; find the equation of the line through two given points, or through one point with a given gradient",true],["GB.MAT.{Y}.ALG.4","10,11","Algebra","Identify and interpret roots, intercepts and turning points of quadratic functions graphically; deduce roots algebraically and turning points by completing the square",true],["GB.MAT.{Y}.ALG.5","10,11","Algebra","Recognise, sketch and interpret graphs of linear functions, quadratic functions, simple cubic functions, the reciprocal function y = 1/x with x ≠ 0, the exponential function y = kˣ for positive values of k, and the trigonometric functions (with arguments in degrees) y = sin x , y = cos x and y = tan x for angles of any size",true],["GB.MAT.{Y}.ALG.6","10,11","Algebra","Sketch translations and reflections of the graph of a given function",true],["GB.MAT.{Y}.ALG.7","10,11","Algebra","Plot and interpret graphs (including reciprocal graphs and exponential graphs) and graphs of non-standard functions in real contexts, to find approximate solutions to problems such as simple kinematic problems involving distance, speed and acceleration",true],["GB.MAT.{Y}.ALG.8","10,11","Algebra","Calculate or estimate gradients of graphs and areas under graphs (including quadratic and other non-linear graphs), and interpret results in cases such as distance-time graphs, velocity-time graphs and graphs in financial contexts",true],["GB.MAT.{Y}.ALG.9","10,11","Algebra","Recognise and use the equation of a circle with centre at the origin; find the equation of a tangent to a circle at a given point",true],["GB.MAT.{Y}.ALG.10","10,11","Algebra","Solve quadratic equations including those that require rearrangement algebraically by factorising, by completing the square and by using the quadratic formula; find approximate solutions using a graph",true],["GB.MAT.{Y}.ALG.11","10,11","Algebra","Solve two simultaneous equations in two variables (linear/linear or linear/quadratic) algebraically; find approximate solutions using a graph",true],["GB.MAT.{Y}.ALG.12","10,11","Algebra","Find approximate solutions to equations numerically using iteration",true],["GB.MAT.{Y}.ALG.13","10,11","Algebra","Translate simple situations or procedures into algebraic expressions or formulae; derive an equation (or two simultaneous equations), solve the equation(s) and interpret the solution"],["GB.MAT.{Y}.ALG.14","10,11","Algebra","Solve linear inequalities in one or two variables, and quadratic inequalities in one variable; represent the solution set on a number line, using set notation and on a graph",true],["GB.MAT.{Y}.ALG.15","10,11","Algebra","Recognise and use sequences of triangular, square and cube numbers, simple arithmetic progressions, Fibonacci type sequences, quadratic sequences, and simple geometric progressions (rⁿ where n is an integer, and r is a positive rational number or a surd) and other sequences",true],["GB.MAT.{Y}.ALG.16","10,11","Algebra","Deduce expressions to calculate the nth term of linear and quadratic sequences.",true],["GB.MAT.{Y}.RPR.1","10,11","Ratio, proportion and rates of change","Compare lengths, areas and volumes using ratio notation and/or scale factors; make links to similarity (including trigonometric ratios)"],["GB.MAT.{Y}.RPR.2","10,11","Ratio, proportion and rates of change","Convert between related compound units (speed, rates of pay, prices, density, pressure) in numerical and algebraic contexts"],["GB.MAT.{Y}.RPR.3","10,11","Ratio, proportion and rates of change","Understand that ‘X is inversely proportional to Y’ is equivalent to ‘X is proportional to 1/Y’; construct and interpret equations that describe direct and inverse proportion",true],["GB.MAT.{Y}.RPR.4","10,11","Ratio, proportion and rates of change","Interpret the gradient of a straight line graph as a rate of change; recognise and interpret graphs that illustrate direct and inverse proportion"],["GB.MAT.{Y}.RPR.5","10,11","Ratio, proportion and rates of change","Interpret the gradient at a point on a curve as the instantaneous rate of change; apply the concepts of instantaneous and average rate of change (gradients of tangents and chords) in numerical, algebraic and graphical contexts",true],["GB.MAT.{Y}.RPR.6","10,11","Ratio, proportion and rates of change","Set up, solve and interpret the answers in growth and decay problems, including compound interest and work with general iterative processes.",true],["GB.MAT.{Y}.GEO.1","10,11","Geometry and measures","Interpret and use fractional and negative scale factors for enlargements",true],["GB.MAT.{Y}.GEO.2","10,11","Geometry and measures","Describe the changes and invariance achieved by combinations of rotations, reflections and translations",true],["GB.MAT.{Y}.GEO.3","10,11","Geometry and measures","Identify and apply circle definitions and properties, including: centre, radius, chord, diameter, circumference, tangent, arc, sector and segment"],["GB.MAT.{Y}.GEO.4","10,11","Geometry and measures","Apply and prove the standard circle theorems concerning angles, radii, tangents and chords, and use them to prove related results",true],["GB.MAT.{Y}.GEO.5","10,11","Geometry and measures","Construct and interpret plans and elevations of 3D shapes"],["GB.MAT.{Y}.GEO.6","10,11","Geometry and measures","Interpret and use bearings"],["GB.MAT.{Y}.GEO.7","10,11","Geometry and measures","Calculate arc lengths, angles and areas of sectors of circles"],["GB.MAT.{Y}.GEO.8","10,11","Geometry and measures","Calculate surface areas and volumes of spheres, pyramids, cones and composite solids"],["GB.MAT.{Y}.GEO.9","10,11","Geometry and measures","Apply the concepts of congruence and similarity, including the relationships between lengths, areas and volumes in similar figures",true],["GB.MAT.{Y}.GEO.10","10,11","Geometry and measures","Apply Pythagoras’ Theorem and trigonometric ratios to find angles and lengths in right-angled triangles and, where possible, general triangles in two and three dimensional figures",true],["GB.MAT.{Y}.GEO.11","10,11","Geometry and measures","Know the exact values of sin θ and cos θ for θ = 0°, 30°, 45°, 60° and 90°; know the exact value of tan θ for θ = 0°, 30°, 45° and 60°"],["GB.MAT.{Y}.GEO.12","10,11","Geometry and measures","Know and apply the sine rule, a/sin A = b/sin B = c/sin C, and cosine rule, a² = b² + c² − 2bc cos A, to find unknown lengths and angles",true],["GB.MAT.{Y}.GEO.13","10,11","Geometry and measures","Know and apply Area = ½ ab sin C to calculate the area, sides or angles of any triangle",true],["GB.MAT.{Y}.GEO.14","10,11","Geometry and measures","Describe translations as 2D vectors"],["GB.MAT.{Y}.GEO.15","10,11","Geometry and measures","Apply addition and subtraction of vectors, multiplication of vectors by a scalar, and diagrammatic and column representations of vectors; use vectors to construct geometric arguments and proofs.",true],["GB.MAT.{Y}.PRO.1","10,11","Probability","Apply the property that the probabilities of an exhaustive set of mutually exclusive events sum to one"],["GB.MAT.{Y}.PRO.2","10,11","Probability","Use a probability model to predict the outcomes of future experiments; understand that empirical unbiased samples tend towards theoretical probability distributions, with increasing sample size"],["GB.MAT.{Y}.PRO.3","10,11","Probability","Calculate the probability of independent and dependent combined events, including using tree diagrams and other representations, and know the underlying assumptions"],["GB.MAT.{Y}.PRO.4","10,11","Probability","Calculate and interpret conditional probabilities through representation using expected frequencies with two-way tables, tree diagrams and Venn diagrams.",true],["GB.MAT.{Y}.STA.1","10,11","Statistics","Infer properties of populations or distributions from a sample, whilst knowing the limitations of sampling"],["GB.MAT.{Y}.STA.2","10,11","Statistics","Interpret and construct tables and line graphs for time series data"],["GB.MAT.{Y}.STA.3","10,11","Statistics","Construct and interpret diagrams for grouped discrete data and continuous data, i.e. histograms with equal and unequal class intervals and cumulative frequency graphs, and know their appropriate use",true],["GB.MAT.{Y}.STA.4","10,11","Statistics","Interpret, analyse and compare the distributions of data sets from univariate empirical distributions through: appropriate graphical representation involving discrete, continuous and grouped data, including box plots; appropriate measures of central tendency (including modal class) and spread including quartiles and inter-quartile range",true],["GB.MAT.{Y}.STA.5","10,11","Statistics","Apply statistics to describe a population"],["GB.MAT.{Y}.STA.6","10,11","Statistics","Use and interpret scatter graphs of bivariate data; recognise correlation and know that it does not indicate causation; draw estimated lines of best fit; make predictions; interpolate and extrapolate apparent trends whilst knowing the dangers of so doing."]]$j$::jsonb) AS t(x) LOOP
  FOREACH y IN ARRAY string_to_array(e0->>1, ',')::int[] LOOP
    e := jsonb_build_array(replace(e0->>0, '{Y}', y::text), y, e0->>2, e0->>3, e0->4);
    v_grade := (e->>1) || '. sınıf';
    v_level := CASE WHEN (e->>1)::int <= 4 THEN 'ilkokul' WHEN (e->>1)::int <= 8 THEN 'ortaokul' ELSE 'lise' END;
    v_ks := CASE WHEN (e->>1)::int <= 2 THEN 'KS1' WHEN (e->>1)::int <= 6 THEN 'KS2' WHEN (e->>1)::int <= 9 THEN 'KS3' ELSE 'KS4' END;
    v_unit_label := e->>2;
    v_topic_label := split_part(e->>2, ' – ', 1);
    SELECT id INTO v_subject FROM public.learning_graph_nodes
      WHERE node_type = 'subject' AND subject = 'Matematik' AND grade = v_grade AND is_active ORDER BY created_at LIMIT 1;
    IF v_subject IS NULL THEN RAISE EXCEPTION 'Matematik subject node missing for %', v_grade; END IF;

    INSERT INTO public.learning_graph_nodes (node_key, node_type, label, subject, grade, level, source_type, metadata, is_active)
    VALUES ('unit:gb:' || md5(v_grade || '|' || v_unit_label), 'unit', v_unit_label, 'Matematik', v_grade, v_level, 'curriculum',
      jsonb_build_object('catalog_version', 'v1', 'verification_status', 'verified', 'country', 'GB', 'curriculum_version_id', v_ver), true)
    ON CONFLICT (node_key) DO UPDATE SET updated_at = now() RETURNING id INTO v_unit;
    INSERT INTO public.learning_graph_edges (source_node_id, target_node_id, edge_type, confidence, rationale, source_type, is_verified, curriculum_version_id)
    VALUES (v_unit, v_subject, 'part_of', 1.000, 'DfE Ulusal Müfredatı: ünite - ders bağlantısı', 'curriculum', true, v_ver)
    ON CONFLICT (source_node_id, target_node_id, edge_type) DO NOTHING;

    INSERT INTO public.learning_graph_nodes (node_key, node_type, label, subject, grade, level, source_type, metadata, is_active)
    VALUES ('topic:gb:' || md5(v_grade || '|' || v_unit_label || '|' || v_topic_label), 'topic', v_topic_label, 'Matematik', v_grade, v_level, 'curriculum',
      jsonb_build_object('catalog_version', 'v1', 'verification_status', 'verified', 'country', 'GB', 'curriculum_version_id', v_ver), true)
    ON CONFLICT (node_key) DO UPDATE SET updated_at = now() RETURNING id INTO v_topic;
    INSERT INTO public.learning_graph_edges (source_node_id, target_node_id, edge_type, confidence, rationale, source_type, is_verified, curriculum_version_id)
    VALUES (v_topic, v_unit, 'part_of', 1.000, 'DfE Ulusal Müfredatı: konu - ünite bağlantısı', 'curriculum', true, v_ver)
    ON CONFLICT (source_node_id, target_node_id, edge_type) DO NOTHING;

    INSERT INTO public.learning_graph_nodes (node_key, node_type, label, subject, grade, level, source_type, metadata, is_active)
    VALUES ('objective:catalog:' || md5(lower(e->>0)), 'learning_objective', e->>3, 'Matematik', v_grade, v_level, 'objective_import',
      jsonb_build_object('objective_code', e->>0, 'imported_from', 'gov.uk'), true)
    ON CONFLICT (node_key) DO UPDATE SET updated_at = now() RETURNING id INTO v_obj;
    INSERT INTO public.learning_graph_edges (source_node_id, target_node_id, edge_type, confidence, rationale, source_type, is_verified, curriculum_version_id)
    VALUES (v_obj, v_topic, 'part_of', 1.000, 'DfE Ulusal Müfredatı: kazanım - konu bağlantısı', 'objective_import', true, v_ver)
    ON CONFLICT (source_node_id, target_node_id, edge_type) DO NOTHING;

    INSERT INTO public.learning_objective_catalog
      (objective_code, title, level, grade, subject, unit, topic, source_type, source_reference, verification_status, metadata,
       graph_node_id, topic_node_id, curriculum_version_id)
    VALUES (e->>0, e->>3, v_level, v_grade, 'Matematik', v_unit_label, v_topic_label, 'import',
      'DfE, National curriculum in England: mathematics programmes of study, ' || v_ks || ' (Year ' || (e->>1) || '), ' || v_unit_label || ' (gov.uk, Open Government Licence v3.0)',
      'verified',
      jsonb_build_object('imported_from', 'gov.uk', 'country', 'GB', 'uk_year', (e->>1)::int, 'key_stage', v_ks,
        'higher_tier_content', coalesce((e->>4)::boolean, false),
        'note', 'Year N maps to grade N; KS3/KS4 statements are listed for each year of the key stage'),
      v_obj, v_topic, v_ver)
    ON CONFLICT (objective_code) DO NOTHING;
  END LOOP;
  END LOOP;
END
